    fdatabpl = 4 * ((1LL * width * depth + 31)/32);
    fdatabytes = fdatabpl * height;
    if (imagebytes != 0 && imagebytes != fdatabytes) {
        L_ERROR("invalid imagebytes = %d; not equal to fdatabytes = %d\n",
                procName, imagebytes, fdatabytes);
        return NULL;
    }

